import * as THREE from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'home-ornamental-divider';
  group.position.set(-2.5, 0.7, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const timelines = [];
  let disposed = false;
  let mesh = null;

  const fallbackGeo = new THREE.BoxGeometry(2.0, 0.02, 0.02);
  const fallbackMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(0x16161d),
    metalness: 0.55,
    roughness: 0.5,
  });
  const fallbackMesh = new THREE.Mesh(fallbackGeo, fallbackMat);
  fallbackMesh.name = 'divider-fallback-rule';

  const jewelGeo = new THREE.OctahedronGeometry(0.06, 0);
  const jewelMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(0xff2a38),
    metalness: 0.3,
    roughness: 0.35,
  });
  const jewel = new THREE.Mesh(jewelGeo, jewelMat);
  jewel.name = 'divider-jewel';
  jewel.position.set(0, 0, 0);

  group.add(fallbackMesh);
  group.add(jewel);

  const meshUrl = '/prism-mock/home/nodes/cta-hero.glb';
  try {
    const gltf = ctx.glbLoader.load(meshUrl);
    if (gltf && gltf.scene) {
      mesh = gltf.scene;
      mesh.name = 'divider-mesh';
      group.remove(fallbackMesh);
      group.add(mesh);
    }
  } catch (e) {
    // keep fallback
  }

  const primitives = (config.cinematicPrimitives || []);
  for (const primitive of primitives) {
    if (ctx.primitives[primitive.name]) {
      ctx.primitives[primitive.name](group, primitive.params);
    }
  }

  const baseY = group.position.y;

  function onHover() {
    const tl = gsap.timeline();
    tl.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.push(tl);
  }

  function onHoverOut() {
    const tl = gsap.timeline();
    tl.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.push(tl);
  }

  function onClick() {
    const tl = gsap.timeline();
    tl.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
      yoyo: true,
      repeat: 1,
    });
    timelines.push(tl);

    if (group.userData.emit) {
      group.userData.emit('hub-home.select', { nodeId: config.id || 'home-ornamental-divider' });
    }
  }

  group.userData.handlers = {
    onHover,
    onHoverOut,
    onClick,
  };

  group.userData.cleanup = function cleanup() {
    if (disposed) return;
    disposed = true;

    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;

    fallbackGeo.dispose();
    fallbackMat.dispose();
    jewelGeo.dispose();
    jewelMat.dispose();

    if (mesh) {
      mesh.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
    }
  };

  return group;
}
